-- Subscriptions cell (subscriptions), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA subscriptions;

CREATE FUNCTION subscriptions.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE subscriptions.subscriptions (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    provider                 text NOT NULL CHECK (length(provider) <= 200 AND length(provider) >= 1),
    category                 text NOT NULL DEFAULT 'software',
    owner_scope              text NOT NULL DEFAULT 'solo_empire' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('trial', 'active', 'paused', 'cancelled', 'expired')),
    billing_interval         text NOT NULL DEFAULT 'monthly' CHECK (billing_interval IN ('weekly', 'monthly', 'quarterly', 'yearly', 'one_time', 'usage')),
    amount                   double precision NOT NULL CHECK (amount >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    started_on               date,
    next_billing_date        date,
    cancelled_on             date,
    auto_renew               boolean NOT NULL DEFAULT true,
    account_id               bigint,
    project_id               bigint,
    goal_id                  bigint,
    source_ref               text,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, name, provider, owner_scope)
);
CREATE UNIQUE INDEX subscriptions_legacy ON subscriptions.subscriptions (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX subscriptions_billing_interval ON subscriptions.subscriptions (workspace_id, billing_interval);
CREATE INDEX subscriptions_owner_scope ON subscriptions.subscriptions (workspace_id, owner_scope);
CREATE INDEX subscriptions_provider ON subscriptions.subscriptions (workspace_id, provider);
CREATE INDEX subscriptions_status ON subscriptions.subscriptions (workspace_id, status);

CREATE TABLE subscriptions.subscription_reviews (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    subscription_id          bigint NOT NULL,
    review_date              date NOT NULL,
    period_start             date NOT NULL,
    period_end               date NOT NULL,
    usage_events             integer CHECK (usage_events IS NULL OR (usage_events >= 0)),
    usage_hours              double precision CHECK (usage_hours IS NULL OR (usage_hours >= 0)),
    time_saved_hours         double precision CHECK (time_saved_hours IS NULL OR (time_saved_hours >= 0)),
    revenue_attributed       double precision CHECK (revenue_attributed IS NULL OR (revenue_attributed >= 0)),
    revenue_currency         text CHECK (revenue_currency IS NULL OR (length(revenue_currency) <= 12)),
    value_score              integer CHECK (value_score IS NULL OR (value_score >= 0 AND value_score <= 100)),
    verdict                  text NOT NULL DEFAULT 'insufficient_data' CHECK (verdict IN ('worth_it', 'conditional', 'not_worth_it', 'insufficient_data')),
    evidence                 text,
    notes                    text,
    next_review_date         date,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, subscription_id, review_date),
    FOREIGN KEY (workspace_id, subscription_id) REFERENCES subscriptions.subscriptions (workspace_id, id)
);
CREATE UNIQUE INDEX subscription_reviews_legacy ON subscriptions.subscription_reviews (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX subscription_reviews_subscription_id ON subscriptions.subscription_reviews (workspace_id, subscription_id);
CREATE INDEX subscription_reviews_verdict ON subscriptions.subscription_reviews (workspace_id, verdict);

CREATE TABLE subscriptions.subscription_aliass (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    alias                    text NOT NULL CHECK (length(alias) <= 300 AND length(alias) >= 1),
    subscription_id          bigint,
    mapping_status           text NOT NULL DEFAULT 'unresolved' CHECK (mapping_status IN ('resolved', 'unresolved')),
    evidence                 text,
    source                   text NOT NULL DEFAULT 'subscription-review',
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, alias),
    FOREIGN KEY (workspace_id, subscription_id) REFERENCES subscriptions.subscriptions (workspace_id, id)
);
CREATE UNIQUE INDEX subscription_aliass_legacy ON subscriptions.subscription_aliass (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX subscription_aliass_mapping_status ON subscriptions.subscription_aliass (workspace_id, mapping_status);
CREATE INDEX subscription_aliass_subscription_id ON subscriptions.subscription_aliass (workspace_id, subscription_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE subscriptions.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('subscription', 'subscription-review', 'subscription-alias')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE subscriptions.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON subscriptions.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['subscriptions', 'subscription_reviews', 'subscription_aliass', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE subscriptions.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE subscriptions.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON subscriptions.%I'
                       ' USING (workspace_id = subscriptions.current_workspace())'
                       ' WITH CHECK (workspace_id = subscriptions.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA subscriptions TO subscriptions_api;
GRANT EXECUTE ON FUNCTION subscriptions.current_workspace() TO subscriptions_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON subscriptions.subscriptions, subscriptions.subscription_reviews, subscriptions.subscription_aliass TO subscriptions_api;
GRANT USAGE ON SEQUENCE subscriptions.subscriptions_id_seq, subscriptions.subscription_reviews_id_seq, subscriptions.subscription_aliass_id_seq TO subscriptions_api;
GRANT SELECT, INSERT ON subscriptions.create_keys TO subscriptions_api;
GRANT SELECT, INSERT ON subscriptions.outbox TO subscriptions_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON subscriptions.outbox TO subscriptions_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON subscriptions.outbox TO subscriptions_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA subscriptions TO subscriptions_publisher;
GRANT SELECT ON subscriptions.outbox TO subscriptions_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON subscriptions.outbox TO subscriptions_publisher;
